#!/bin/bash
# Point the Homebrew cask at a published release.
#
# The version and the sha256 were regenerated by hand every release, which is
# two chances per release to ship a cask that installs the previous build or
# refuses to install at all. Neither failure is visible from the repo: the
# checksum only disagrees with reality on someone else's machine.
#
#   bin/update-cask.sh            # newest published release
#   bin/update-cask.sh 0.2.8      # a specific one
#
# The checksum is taken from the release asset, never from a local build, so it
# describes the bytes a user actually downloads.
set -euo pipefail
cd "$(dirname "$0")/.."

REPO="SirSicard/inkwell"
CASK="packaging/homebrew/inkwell.rb"

VERSION="${1:-}"
if [ -z "$VERSION" ]; then
  VERSION=$(gh release view --repo "$REPO" --json tagName --jq '.tagName' | sed 's/^v//')
  echo "Newest published release: $VERSION"
fi

DMG="Inkwell_${VERSION}_aarch64.dmg"
URL="https://github.com/$REPO/releases/download/v$VERSION/$DMG"

# A draft release is not downloadable by a user, so a cask pointing at one is
# broken for everyone but the maintainer. Refuse rather than write it.
if [ "$(gh release view "v$VERSION" --repo "$REPO" --json isDraft --jq '.isDraft')" = "true" ]; then
  echo "v$VERSION is still a draft; publish it before pointing the cask at it." >&2
  exit 1
fi

TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
echo "Downloading $DMG"
gh release download "v$VERSION" --repo "$REPO" --pattern "$DMG" --dir "$TMP"
SHA=$(shasum -a 256 "$TMP/$DMG" | cut -d' ' -f1)
echo "sha256: $SHA"

python3 - "$CASK" "$VERSION" "$SHA" <<'PY'
import re, sys
path, version, sha = sys.argv[1:4]
s = open(path).read()
s, n_v = re.subn(r'^(  version ")[^"]+(")', rf'\g<1>{version}\g<2>', s, count=1, flags=re.M)
s, n_s = re.subn(r'^(  sha256 ")[0-9a-f]{64}(")', rf'\g<1>{sha}\g<2>', s, count=1, flags=re.M)
if n_v != 1 or n_s != 1:
    # The cask's shape changed and the rewrite silently matched nothing, which
    # would leave the old values in place and report success.
    sys.exit(f"cask rewrite failed: matched version={n_v} sha256={n_s}, expected 1 each")
open(path, "w").write(s)
PY

# Read the file back rather than trusting the write, and prove the URL the cask
# now names actually serves something.
GOT_V=$(grep -m1 '^  version "' "$CASK" | sed 's/.*"\(.*\)"/\1/')
GOT_S=$(grep -m1 '^  sha256 "' "$CASK" | sed 's/.*"\(.*\)"/\1/')
[ "$GOT_V" = "$VERSION" ] || { echo "verify failed: cask says version $GOT_V" >&2; exit 1; }
[ "$GOT_S" = "$SHA" ] || { echo "verify failed: cask sha256 does not match" >&2; exit 1; }

CODE=$(curl -sI -o /dev/null -w '%{http_code}' -L "$URL")
[ "$CODE" = "200" ] || { echo "verify failed: $URL returned HTTP $CODE" >&2; exit 1; }

echo
git --no-pager diff --stat -- "$CASK" || true
echo "Cask now points at v$VERSION, checksum verified against the published dmg."
